head.script:
scwin.trigger1_onclick = function(e) {
	if (WebSquare._xv !== "SP5") { requires("uiplugin.popup"); }
	var opts = {
		"id": "popup_window_wframe",
		"type": "wfamePopup",
		"width": 300 + "px",
		"height": 300 + "px",
		"top": 250,
		"left": 250,
		"popupName": "popup_wframe",
		"modal": false,
		"title": "paramTest",
		"frameMode": "wframe"
	};
	WebSquare.util.openPopup("/sample/common_link/wframe_event_order_WPFF-218_(WSQ-3498)_tabControl.xml", opts);
};
